"use client";

import { useState } from "react";
import { LehceTipi } from "@/types/dictionary";
import { GununKelimesiKart } from "@/components/GununKelimesiKart";
import { IstatistikBandi } from "@/components/IstatistikBandi";

export default function HomePage() {
  const [seciliLehce, setSeciliLehce] = useState<LehceTipi>("Tümü");
  const [wordsCount, setWordsCount] = useState<number>(0);

  return (
    <main className="container mx-auto p-4">
      <IstatistikBandi wordsCount={wordsCount} aktifTema={aktifTema} />
      
      <GununKelimesiKart
        gununKelimesi={gununKelimesi}
        karanlikMod={karanlikMod}
        metinBoyutu={metinBoyutu}
        tema={aktifTema}
        onSelect={() =>
          handleKelimeSec({
            kelime: gununKelimesi.kelime,
            kaynaklar: [gununKelimesi],
          })
        }
      />
    </main>
  );
}