interface IstatistikBandiProps {
  wordsCount: number;
  aktifTema: { cizgi: string; yaziAlt: string };
}

export const IstatistikBandi = ({ wordsCount, aktifTema }: IstatistikBandiProps) => (
  <div className="grid grid-cols-3 gap-4 py-4 border-y" style={{ borderColor: aktifTema.cizgi }}>
    <div className="text-center">
      <div className="text-2xl font-extrabold text-[#FF4030]">
        {wordsCount.toLocaleString("tr-TR")}
      </div>
      <div className="text-xs" style={{ color: aktifTema.yaziAlt }}>
        Kelime
      </div>
    </div>
    <div className="text-center">
      <div className="text-2xl font-extrabold text-[#FF4030]">34</div>
      <div className="text-xs" style={{ color: aktifTema.yaziAlt }}>
        Sözlük
      </div>
    </div>
    <div className="text-center">
      <div className="text-2xl font-extrabold text-[#FF4030]">100%</div>
      <div className="text-xs" style={{ color: aktifTema.yaziAlt }}>
        Açık Lisans
      </div>
    </div>
  </div>
);